INSERT INTO FactHoldings (SK_CustomerID, SK_AccountID, SK_SecurityID, SK_CompanyID, CurrentPrice, SK_DateID, SK_TimeID, TradeID, CurrentTradeID, CurrentHolding, BatchID) SELECT DT.SK_CustomerID, DT.SK_AccountID, DT.SK_SecurityID, DT.SK_CompanyID, TRY_CAST(DT.TradePrice AS INT) AS CurrentPrice, COALESCE(DT.SK_CloseDateID, DT.SK_CreateDateID) AS SK_DateID, COALESCE(DT.SK_CloseTimeID, DT.SK_CreateTimeID) AS SK_TimeID, HH.HH_H_T_ID AS TradeID, HH.HH_T_ID AS CurrentTradeID, HH.HH_AFTER_QTY AS CurrentHolding, 1 AS BatchID FROM Source.HoldingHistory AS HH, DimTrade AS DT WHERE HH.HH_T_ID = DT.TradeID;
